declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-102';
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 The Pastoral Letters and Philemon$j$, $j${"readings": [{"title": "1 Timothy 4 (King James Version)", "url": "/portal/bible/1Timothy/4"}, {"title": "2 Timothy 3 (King James Version)", "url": "/portal/bible/2Timothy/3"}, {"title": "Titus 2 (King James Version)", "url": "/portal/bible/Titus/2"}, {"title": "Philemon 1 (King James Version)", "url": "/portal/bible/Philemon/1"}], "body": "Read 1 Timothy 4, 2 Timothy 3, Titus 2 and Philemon 1 in the King James Version. Then read this lesson.\n\nThe letters to Timothy and Titus are called the pastoral letters because Paul wrote them to young leaders who were caring for churches. Timothy served at Ephesus and Titus served on the island of Crete. Paul told Timothy not to let anyone despise his youth but to be an example of the believers. In 2 Timothy, which is probably the last letter Paul wrote, he taught that all scripture is given by inspiration of God and is profitable for doctrine, reproof, correction and instruction in righteousness. Near the end of his life Paul wrote that he had fought a good fight, finished his course and kept the faith. In Titus he taught that the grace of God teaches us to live soberly, righteously and godly. Philemon is a short and personal letter in which Paul asked his friend Philemon to receive back Onesimus, who had left, as a brother beloved.\n\nKey words: pastor, example, inspiration, scripture, forgiveness.\n\nYour task: (1) Tell what Paul asked Timothy to be in 1 Timothy 4:12. (2) Write 2 Timothy 3:16 in your own words. (3) Explain what Paul asked Philemon to do for Onesimus.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "This is our last lesson on the letters of Paul. Today we study the letters to Timothy and Titus and the short letter to Philemon. First and Second Timothy and Titus are called the pastoral letters, because Paul wrote them to young leaders who were taking care of churches.\n\nTimothy was Paul's spiritual son. He was probably a young man when Paul invited him to join his travels in Acts 16. Later Timothy served in Ephesus. Paul gave him this advice in First Timothy 4:12, Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity. A young person who lives well can lead others. Paul also reminded him in First Timothy 2:5, For there is one God, and one mediator between God and men, the man Christ Jesus;\n\nSecond Timothy is the last letter we have from Paul. He was in prison again, and he knew his time was short. He told Timothy in 2 Timothy 1:7, For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind. He urged Timothy to keep to the Word. Second Timothy 3:15 says, And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus. And verse 16 says, All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness: Verse 17 says the result, That the man of God may be perfect, throughly furnished unto all good works.\n\nAt the end of the letter Paul looked back on his life. In 2 Timothy 4:7 he wrote, I have fought a good fight, I have finished my course, I have kept the faith: And verse 8 says, Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing. Paul finished well, and we are invited to finish well too.\n\nTitus served on the island of Crete, where he was to set the churches in order. Paul reminded him in Titus 2:11, For the grace of God that bringeth salvation hath appeared to all men, And the next verse says that grace teaches us to live soberly, righteously and godly. In Titus 3:5 Paul wrote, Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;\n\nFinally there is Philemon, the shortest of Paul's letters. Philemon was a believer in Colossae, and his servant Onesimus had left him. Onesimus met Paul and became a believer. Paul sent him back with a letter. In Philemon 1:16 Paul asked Philemon to receive him, Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord? And in verse 17 he wrote, If thou count me therefore a partner, receive him as myself. Paul even offered to pay any debt in verse 18, If he hath wronged thee, or oweth thee ought, put that on mine account; This is a picture of forgiveness, and it reminds us of how Christ paid our debt.\n\nYour task is to tell what Paul asked Timothy to be, write 2 Timothy 3:16 in your own words, and explain what Paul asked Philemon to do for Onesimus. Then take the four question check and the Unit 4 quiz.\n\nPaul finished his course, and by God's grace we can finish ours. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 The Pastoral Letters and Philemon$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: One Letter, One Message$j$, $j${"prompt": "Choose one of these letters from this unit: Ephesians, Philippians, Colossians, 1 Thessalonians, 2 Timothy or Philemon. Write one paragraph of 150 to 200 words. Tell who the letter was written to, state its main message, quote one verse from it in the King James Version with the reference, and explain how that message helps a student today.", "rubric": "Total 100. Names the readers and setting of the letter: 20. States the main message accurately: 30. Quotes a verse correctly with the reference and applies it: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: One Letter, One Message$j$);
end
